    _cli(["materializar", "--dir", pasta, "--trabalho", "t-sem-turnos",
          "--etapa", "alfa", "--ordem", "1", "--teto", "3"],
         entrada=json.dumps({"structured_output":
                             json.loads(EXEMPLO_DA_ISSUE)}))
    caso("sem o argumento o campo não nasce — opcional de verdade",
         "turnos" not in _ler(pasta, "t-sem-turnos", "01-alfa-c1.json"))
    com_forja = dict(json.loads(EXEMPLO_DA_ISSUE), turnos=999)
