    _o_teto_declarado_invalido_morre_com_erro_de_uso(pasta, caso)
    _o_lixo_ilegivel_nao_cala_os_vizinhos(pasta, caso)
    _a_amostra_e_deterministica(pasta, caso)
    _a_semente_da_amostra_vem_do_texto(caso)
