FRONTMATTER = re.compile(r"^---\\n(.*?)\\n---\\n", re.S)
CAMPO_NOME = re.compile(r"^name:\\s*(.+)$", re.M)
CAMPO_DESCRICAO = re.compile(r"^description:\\s*(.+)$", re.M)
CAMPO_DAS_FERRAMENTAS = re.compile(r"^tools:\\s*\\S", re.M)
